ON CONFLICT (category_id, document_id) DO NOTHING;

-- ── 8. Índices ────────────────────────────────────────────────────────────
CREATE INDEX IF NOT EXISTS idx_categories_parent   ON public.categories(parent_id);
CREATE INDEX IF NOT EXISTS idx_catdocs_category    ON public.category_documents(category_id);
CREATE INDEX IF NOT EXISTS idx_clientflows_client  ON public.client_document_flows(client_id);
CREATE INDEX IF NOT EXISTS idx_clientflows_catcat  ON public.client_document_flows(category_id, catalog_id);

-- ── 9. Seed fluxo padrão para clientes existentes ────────────────────────
--  Copia category_documents → client_document_flows para cada cliente já cadastrado.
--  ON CONFLICT DO NOTHING garante idempotência (re-aplicável sem duplicar).
INSERT INTO public.client_document_flows (client_id, category_id, catalog_id, required)
SELECT c.id, cd.category_id, cd.document_id, true
FROM   public.clients c
CROSS  JOIN public.category_documents cd
ON CONFLICT (client_id, category_id, catalog_id) DO NOTHING;

DO $$
BEGIN
  RAISE NOTICE 'patch_017 aplicado: % categorias, % documentos, % vínculos cat→doc, % fluxos cliente',
    (SELECT COUNT(*) FROM public.categories),
    (SELECT COUNT(*) FROM public.documents_catalog),
    (SELECT COUNT(*) FROM public.category_documents),
    (SELECT COUNT(*) FROM public.client_document_flows);
END $$;
